1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { listHostingAccounts } from "@/lib/actions-hosting";
4	import { HostingClient } from "@/components/customer/HostingClient";
5	
6	export const dynamic = "force-dynamic";
7	
8	export default async function HostingPage() {
9	  await requireUser();
10	  const [plans, accounts] = await Promise.all([
11	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
12	    listHostingAccounts(),
13	  ]);
14	  const planViews = plans.map((p) => ({
15	    id: p.id,
16	    name: p.name,
17	    priceCents: p.priceCents,
18	    diskGB: p.diskGB,
19	    maxSites: p.maxSites,
20	    maxDatabases: p.maxDatabases,
21	    bandwidthTB: p.bandwidthTB,
22	    mailboxes: p.mailboxes,
23	    freeMigration: p.freeMigration,
24	    featured: p.featured,
25	    tagline: p.tagline,
26	  }));
27	  return <HostingClient plans={planViews} accounts={accounts} />;
28	}
