1	"use client";
2	
3	import { useState, type ReactNode } from "react";
4	
5	const TABS = [
6	  "Overview",
7	  "Control panel",
8	  "Metrics",
9	  "Console",
10	  "Files",
11	  "Snapshots",
12	  "Backups",
13	  "Networking",
14	  "Resize",
15	  "Activity",
16	] as const;
17	
18	// Customer-facing label overrides. The internal tab key stays "resize" so the
19	// ?tab=resize deep-links, the panels map and every internal reference keep
20	// working untouched — only the text the customer reads changes to "Upgrade".
21	const TAB_LABELS: Record<string, string> = {
22	  resize: "Upgrade",
23	};
24	
25	export function ServerTabs({
26	  initialTab,
27	  overview,
28	  controlPanel,
29	  metrics,
30	  console: consolePanel,
31	  files,
32	  snapshots,
33	  backups,
34	  networking,
35	  resize,
36	  activity,
37	}: {
38	  initialTab?: string;
39	  overview: ReactNode;
40	  controlPanel: ReactNode;
41	  metrics: ReactNode;
42	  console: ReactNode;
43	  files: ReactNode;
44	  snapshots: ReactNode;
45	  backups: ReactNode;
46	  networking: ReactNode;
47	  resize: ReactNode;
48	  activity: ReactNode;
49	}) {
50	  const keys = TABS.map((t) => t.toLowerCase());
51	  const [tab, setTab] = useState<string>(
52	    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
53	  );
54	
55	  const panels: Record<string, ReactNode> = {
56	    overview,
57	    "control panel": controlPanel,
58	    metrics,
59	    console: consolePanel,
60	    files,
61	    snapshots,
62	    backups,
63	    networking,
64	    resize,
65	    activity,
66	  };
67	
68	  return (
69	    <div>
70	      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
71	        {TABS.map((t) => {
72	          const k = t.toLowerCase();
73	          const active = tab === k;
74	          return (
75	            <button
76	              key={k}
77	              type="button"
78	              onClick={() => {
79	                setTab(k);
80	                window.history.replaceState(null, "", `?tab=${k}`);
81	              }}
82	              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
83	                active
84	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
85	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
86	              }`}
87	            >
88	              {TAB_LABELS[k] ?? t}
89	            </button>
90	          );
91	        })}
92	      </div>
93	      <div className="animate-fade-up">{panels[tab]}</div>
94	    </div>
95	  );
96	}
