541	function FileManager({ accountId }: { accountId: string }) {
542	  const [open, setOpen] = useState(false);
543	  const [path, setPath] = useState("public_html");
544	  const [entries, setEntries] = useState<FsEntryView[]>([]);
545	  const [err, setErr] = useState("");
546	  const [busy, setBusy] = useState(false);
547	  const [loaded, setLoaded] = useState(false);
548	  const fileRef = useRef<HTMLInputElement>(null);
549	
550	  async function load(p: string) {
551	    setBusy(true); setErr("");
552	    const r = await hostingListFiles(accountId, p);
553	    setBusy(false); setLoaded(true);
554	    if (r.error) setErr(r.error); else { setEntries(r.entries ?? []); setPath(r.path ?? p); }
555	  }
556	  useEffect(() => { if (open) load(path); /* eslint-disable-next-line */ }, [open]);
557	
558	  const parent = () => { const parts = path.split("/").filter(Boolean); parts.pop(); load(parts.join("/") || "public_html"); };
559	  async function upload(files: FileList | null) {
560	    if (!files?.length) return;
561	    setBusy(true);
562	    for (const f of Array.from(files)) {
563	      const fd = new FormData(); fd.append("file", f);
564	      await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd }).catch(() => {});
565	    }
566	    if (fileRef.current) fileRef.current.value = "";
567	    load(path);
568	  }
569	
570	  if (!open) return <button className="text-xs font-medium text-brand-300 hover:underline" onClick={() => setOpen(true)}>Open file manager</button>;
571	  return (
572	    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
573	      <div className="mb-2 flex items-center justify-between">
574	        <span className="font-mono text-xs text-slate-400">/{path}</span>
575	        <div className="flex items-center gap-2 text-xs">
576	          <button className="text-brand-300 hover:underline" onClick={() => fileRef.current?.click()}>Upload</button>
577	          <input ref={fileRef} type="file" multiple className="hidden" onChange={(e) => upload(e.target.files)} />
578	          <button className="text-slate-400 hover:underline" onClick={async () => { const n = prompt("New folder name"); if (n) { const r = await hostingMkdir(accountId, path, n); if (r.error) alert(r.error); else load(path); } }}>New folder</button>
579	          <button className="text-slate-500 hover:underline" onClick={() => setOpen(false)}>close</button>
580	        </div>
581	      </div>
582	      {err && <p className="text-xs text-amber-300">{err}</p>}
583	      {busy && <p className="text-xs text-slate-500">Loading…</p>}
584	      {loaded && !busy && !err && entries.length === 0 && path === "public_html" && (
585	        <p className="px-1 py-2 text-xs text-slate-500">This folder is empty. Upload your site files here, or install an app above.</p>
586	      )}
587	      <ul className="max-h-56 overflow-auto text-xs">
588	        {path !== "public_html" && path !== "" && (
589	          <li><button className="text-slate-400 hover:underline" onClick={parent}>⬆ ..</button></li>
590	        )}
591	        {entries.map((e) => (
592	          <li key={e.name} className="flex items-center justify-between py-0.5">
593	            {e.isDir ? (
594	              <button className="text-brand-200 hover:underline" onClick={() => load(`${path}/${e.name}`)}>📁 {e.name}</button>
595	            ) : (
596	              <a className="text-slate-300 hover:underline" href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${e.name}`)}`}>📄 {e.name}</a>
597	            )}
598	            <span className="flex items-center gap-2 text-slate-500">
599	              {!e.isDir && <span>{(e.size / 1024).toFixed(0)} KB</span>}
600	              <button className="text-red-400 hover:underline" onClick={async () => { if (confirm(`Delete ${e.name}?`)) { const r = await hostingDeleteFile(accountId, `${path}/${e.name}`, e.isDir); if (r.error) alert(r.error); else load(path); } }}>del</button>
601	            </span>
602	          </li>
603	        ))}
604	      </ul>
605	    </div>
606	  );
607	}
