55	/**
56	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
57	 * as every other paid path: no spending while impersonating, verified email,
58	 * wallet charge in the same tx that creates the record. The account starts
59	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
60	 * enabled — see worker/hosting.ts).
61	 */
62	export async function orderHostingAccount(planId: string, domain: string): Promise<HostingResult> {
63	  const user = await requireUser();
64	  await assertNotImpersonating();
65	  const unverified = await emailVerificationError(user);
66	  if (unverified) return { error: unverified };
67	
68	  const name = normalizeHostingDomain(domain);
69	  if (!name) return { error: "Enter a domain." };
70	  if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
71	
72	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
73	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
74	
75	  // One account per domain across ALL customers — same cross-tenant guard as
76	  // email subscriptions (a shared vhost keys on server_name).
77	  const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
78	  if (dupe) {
79	    return {
80	      error:
81	        dupe.userId === user.id
82	          ? "You already have a hosting account for this domain."
83	          : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
84	    };
85	  }
86	
87	  const node = await scheduleHostingNode();
88	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
89	
90	  const promo = currentPromo(new Date());
91	  const chargeCents = promoPriceCents(plan.priceCents, promo);
92	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
93	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
94	
95	  const limits = planLimits(plan);
96	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
97	
98	  let accountId = "";
99	  try {
100	    await db.$transaction(async (tx) => {
101	      await debitWallet(tx, user.id, chargeCents);
102	      await tx.walletTransaction.create({
103	        data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting: ${plan.name} for ${name}${promoNote}` },
104	      });
105	      const acct = await tx.hostingAccount.create({
106	        data: {
107	          userId: user.id,
108	          hostingNodeId: node.id,
109	          planId: plan.id,
110	          username,
111	          primaryDomain: name,
112	          status: "PENDING",
113	          diskQuotaMB: limits.diskGB * 1024,
114	          maxSites: limits.maxSites,
115	          maxDatabases: limits.maxDatabases,
116	          expiresAt: addMonths(new Date(), 1),
117	        },
118	      });
119	      accountId = acct.id;
120	    });
121	  } catch (e) {
122	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
123	  }
124	
125	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
126	  revalidatePath("/dashboard/hosting");
127	  return { ok: true, accountId };
128	}
