217	/** Create a scoped database for an account (within the plan's maxDatabases). */
218	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
219	  const user = await requireUser();
220	  await assertNotImpersonating();
221	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
222	  if (!a) return { error: "Account not found." };
223	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
224	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
225	  // A short, safe suffix keyed off the account username: <user>_<slug>.
226	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
227	  const name = `${a.username}_${slug}`.slice(0, 64);
228	  const dbUser = name.slice(0, 32);
229	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
230	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
231	  // Count + create in ONE serializable transaction, so concurrent creates can't
232	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
233	  try {
234	    await db.$transaction(async (tx) => {
235	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
236	      if (n >= a.maxDatabases) throw new Error("CAP");
237	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
238	    }, { isolationLevel: "Serializable" });
239	  } catch (e) {
240	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
241	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
242	    return { error: "A database with that name already exists, or the request raced — try again." };
243	  }
244	  revalidatePath("/dashboard/hosting");
245	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
246	  return { ok: true, password };
247	}
