269	/** Recent panel tasks for an account (so the UI can show progress + one-time results). */
270	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
271	  const user = await requireUser();
272	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
273	  if (!a) return [];
274	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
275	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
276	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
277	  // then clear it so it isn't shown again on the next poll.
278	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
279	  const toClear = rows.filter((t) => t.status === "DONE" && t.result);
280	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
281	  return out;
282	}
