308	      accountId,
309	      kind: "WORDPRESS_INSTALL",
310	      payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: user.email }),
