1	/**
2	 * Shared-hosting account provisioner (Phase 1).
3	 *
4	 * ┌────────────────────────────────────────────────────────────────────────┐
5	 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
6	 * │                                                                          │
7	 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
8	 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
9	 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
10	 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
11	 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
12	 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
13	 * │ production until this has been (1) reviewed as a security change,        │
14	 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
15	 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
16	 * │                                                                          │
17	 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
18	 * │ so a bad config can never lock the box out — but it still deserves the   │
19	 * │ staging pass.                                                            │
20	 * └────────────────────────────────────────────────────────────────────────┘
21	 *
22	 * Everything a shell touches is validated through the tested pure helpers in
23	 * lib/hosting.ts BEFORE interpolation.
24	 */
25	
26	import { Client } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { promises as dns } from "node:dns";
29	import { db } from "../lib/db";
30	import { SANDBOX } from "../lib/sandbox";
31	import { decryptSecret, encryptSecret } from "../lib/crypto-box";
32	import {
33	  isValidUnixUsername,
34	  isValidHostingDomain,
35	  planLimits,
36	  diskQuotaBlocks,
37	  accountPaths,
38	  accountFsPlan,
39	  fpmPoolConfig,
40	  buildScopedGrantSql,
41	} from "../lib/hosting";
42	
43	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
44	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
45	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
46	 *  doesn't treat them as command substitution. */
47	function sqlForMysqlExec(sql: string): string {
48	  return sql.replace(/`/g, "\\`");
49	}
50	
51	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
52	const CONNECT_TIMEOUT_MS = 20_000;
53	const STEP_TIMEOUT_MS = 60_000;
54	
55	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
56	function strongPassword(len = 22): string {
57	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
58	  const bytes = randomBytes(len);
59	  let out = "";
60	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
61	  return out;
62	}
63	
64	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
65	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
66	  if (!password) throw new Error("Hosting node has no root credential on record.");
67	  const conn = new Client();
68	  await new Promise<void>((resolve, reject) => {
69	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
70	    conn
71	      .on("ready", () => { clearTimeout(timer); resolve(); })
72	      .on("error", (e) => { clearTimeout(timer); reject(e); })
73	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
74	  });
75	  return conn;
76	}
77	
78	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
79	  return new Promise((resolve, reject) => {
80	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
81	    conn.exec(command, (err, stream) => {
82	      if (err) { clearTimeout(timer); return reject(err); }
83	      let out = "";
84	      stream
85	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
86	        .on("data", (d: Buffer) => { out += d.toString(); })
87	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
88	    });
89	  });
90	}
91	
92	async function run(conn: Client, label: string, cmd: string): Promise<void> {
93	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
94	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
95	}
