299	export async function hostingProvisionSweep(): Promise<void> {
300	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
301	  for (const p of pending) await provisionHostingAccount(p.id).catch((e) => console.error(`[hosting] provision ${p.id} failed`, e));
302	}
