304	// ---- SSL sweep (post-DNS, no sshd risk) ------------------------------------
305	
306	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
307	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
308	  try {
309	    const a = await dns.resolve4(domain);
310	    return a.includes(ip);
311	  } catch {
312	    return false;
313	  }
314	}
