352	/** Measure real disk + inode usage per ACTIVE account and store it, so the panel
353	 *  shows live meters instead of a placeholder. Read-only on the node (du + find);
354	 *  inert until enabled. Polled on the SSL-sweep cadence. */
355	export async function hostingUsageSweep(): Promise<void> {
356	  if (SANDBOX || !ENABLED) return;
357	  const accts = await db.hostingAccount.findMany({ where: { status: "ACTIVE" }, include: { node: true }, take: 50 });
358	  for (const a of accts) {
359	    try {
360	      if (!isValidUnixUsername(a.username)) continue;
361	      const conn = await connectNode(a.node);
362	      try {
363	        const du = await exec(conn, `du -sm /home/${a.username} 2>/dev/null | cut -f1`, 60_000);
364	        const inodes = await exec(conn, `find /home/${a.username} -xdev 2>/dev/null | wc -l`, 60_000);
365	        const diskUsedMB = parseInt(du.out.trim(), 10);
366	        const inodesUsed = parseInt(inodes.out.trim(), 10);
367	        await db.hostingAccount.update({
368	          where: { id: a.id },
369	          data: {
370	            diskUsedMB: Number.isFinite(diskUsedMB) ? diskUsedMB : null,
371	            inodesUsed: Number.isFinite(inodesUsed) ? inodesUsed : null,
372	            usageAt: new Date(),
373	          },
374	        });
375	      } finally {
376	        try { conn.end(); } catch { /* */ }
377	      }
378	    } catch (e) {
379	      console.error(`[hosting] usage sweep ${a.id} failed`, e);
380	    }
381	  }
382	}
