393	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
394	 *  the vhost never needs editing). */
395	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
396	  const version = String(JSON.parse(payload || "{}").version ?? "");
397	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
398	  const { home, webroot } = accountPaths(a.username);
399	  if (version !== a.phpVersion) {
400	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
401	  }
402	  await writeFpmPool(conn, a.username, home, webroot, version);
403	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
404	}
