406	// ---- Account lifecycle (suspend / unsuspend / terminate) --------------------
407	// All three validate the username first (it flows into shell), and are written to
408	// be idempotent + safe to re-run. They only touch this account's own files.
409	
410	type LifecycleAccount = { id: string; username: string; phpVersion: string };
411	
412	// Validate BOTH shell-bound fields up front. username is a strict allowlist;
413	// phpVersion is stored (schema default "8.3") but re-checked here so it can never
414	// carry anything but `\d.\d` into an `rm`/`systemctl` line (security audit LOW-1).
415	function assertLifecycleSafe(a: LifecycleAccount): void {
416	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
417	  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
418	}
