420	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
421	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
422	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
423	  assertLifecycleSafe(a);
424	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
425	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
426	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
427	}
428	
429	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
430	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
431	  assertLifecycleSafe(a);
432	  const { home, webroot } = accountPaths(a.username);
433	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
434	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
435	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
436	}
