438	/** Fully deprovision: remove the vhost + FPM pool, delete the jailed user and its
439	 *  home, and drop every database AND db-user scoped to this account (`<user>_*`). */
440	async function taskTerminate(conn: Client, a: LifecycleAccount): Promise<void> {
441	  assertLifecycleSafe(a);
442	  await run(conn, "terminate: remove vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf /etc/nginx/sites-available/hosting-${a.username}.conf; systemctl reload nginx 2>/dev/null || true`);
443	  await run(conn, "terminate: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
444	  // Drop this account's scoped databases (`<user>_*`) AND the matching db-users
445	  // (named `<user>_<slug>` / `<user>_wp`, NOT bare `<user>` — audit MEDIUM-2).
446	  await run(conn, "terminate: drop scoped dbs + users", `for d in $(mysql -N -e "SHOW DATABASES LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP DATABASE \\\`$d\\\`" 2>/dev/null; done; for u in $(mysql -N -e "SELECT User FROM mysql.user WHERE User LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP USER IF EXISTS '$u'@'localhost'" 2>/dev/null; done; true`);
447	  await run(conn, "terminate: delete user + home", `pkill -u ${a.username} 2>/dev/null; sleep 1; userdel -r ${a.username} 2>/dev/null || true`);
448	}
