450	/** One-click WordPress: create the DB, drop WordPress in the webroot, install it
451	 *  as the jailed account user via WP-CLI. Returns the admin login (shown once). */
452	/** Re-check the plan DB cap at DB-creation time. The worker processes tasks
453	 *  SEQUENTIALLY, so this is the serialization point that closes the TOCTOU race
454	 *  the action-level gate can't (audit 2026-08-01). */
455	async function assertDbCap(accountId: string, maxDatabases: number): Promise<void> {
456	  const n = await db.hostingDatabase.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
457	  if (n >= maxDatabases) throw new Error("Your plan's database limit is reached.");
458	}
