460	async function taskWordpressInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
461	  await assertDbCap(a.id, a.maxDatabases);
462	  const p = JSON.parse(payload || "{}") as { dbName?: string; dbUser?: string; dbPassEnc?: string; adminUser?: string; adminPassEnc?: string; adminEmail?: string };
463	  const dbName = String(p.dbName ?? "");
464	  const dbUser = String(p.dbUser ?? "");
465	  const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
466	  const adminUser = String(p.adminUser ?? "");
467	  const adminPass = (p.adminPassEnc ? decryptSecret(p.adminPassEnc) : "") ?? "";
468	  const adminEmail = String(p.adminEmail ?? "");
469	  if (!SAFE_ID.test(dbName) || !SAFE_ID.test(dbUser.slice(0, 32)) || !dbPass) throw new Error("invalid db identifiers");
470	  if (!/^[A-Za-z0-9_]{1,32}$/.test(adminUser) || !/^[A-Za-z0-9]{8,64}$/.test(adminPass) || !SAFE_EMAIL.test(adminEmail)) throw new Error("invalid admin identifiers");
471	  const u = a.username;
472	  const d = a.primaryDomain;
473	  if (!isValidUnixUsername(u) || !isValidHostingDomain(d)) throw new Error("unsafe account");
474	  const { webroot } = accountPaths(u);
475	
476	  await run(conn, "wp-cli", `command -v wp >/dev/null 2>&1 || (curl -fsSL https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /usr/local/bin/wp && chmod +x /usr/local/bin/wp)`);
477	  const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
478	  await run(conn, "wp db", `mysql -e "${sql}"`);
479	  const wp = `sudo -u ${u} -H wp --path=${webroot}`;
480	  await run(conn, "wp download", `${wp} core download --force`);
481	  await run(conn, "wp config", `${wp} config create --dbname=${dbName} --dbuser=${dbUser} --dbpass='${dbPass}' --force`);
482	  await run(conn, "wp install", `${wp} core install --url='https://${d}' --title='${d}' --admin_user='${adminUser}' --admin_password='${adminPass}' --admin_email='${adminEmail}' --skip-email`);
483	  await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
484	  // Shown ONCE in the panel, then the task result is cleared.
485	  return JSON.stringify({ adminUser, adminPassword: adminPass, url: `https://${d}/wp-admin/` });
486	}
