508	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
509	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
510	  const slug = String(p.slug ?? "");
511	  const recipe = APP_RECIPES[slug];
512	  if (!recipe) throw new Error("unknown app");
513	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
514	  const u = a.username;
515	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
516	  const { webroot } = accountPaths(u);
517	  const isBz2 = recipe.url.endsWith(".bz2");
518	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
519	  // Download + extract into the webroot AS the account user (jailed).
520	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
521	  let dbInfo = "";
522	  if (recipe.needsDb) {
523	    const dbName = String(p.dbName ?? "");
524	    const dbUser = String(p.dbUser ?? "");
525	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
526	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
527	    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
528	    await run(conn, "app db", `mysql -e "${sql}"`);
529	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
530	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
531	  }
532	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
533	}
