535	/** Archive the account's home + DB dumps to a node-local backups dir.
536	 *
537	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
538	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
539	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
540	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
541	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
542	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
543	 * dumps root-owned and off the tenant tree means the archived SQL is always our
544	 * own mysqldump output, never tenant-controlled. */
545	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
546	  const u = a.username;
547	  const dir = `/var/hosting-backups/${u}`;
548	  const dumpDir = `${dir}/dbdump`;
549	  const path = `${dir}/${tsLabel}.tar.gz`;
550	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
551	  // tenant can neither read nor tamper with it.
552	  await run(
553	    conn,
554	    "dump dbs",
555	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
556	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
557	  );
558	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
559	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
560	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
561	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
562	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
563	  // Retain the newest 5 per account; delete older files + rows.
564	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
565	  for (const old of all.slice(5)) {
566	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
567	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
568	  }
569	}
