571	/** Restore a backup over the account (destructive: overwrites files + DBs).
572	 *
573	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
574	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
575	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
576	 * database, and the SQL content is our own dump, not anything the tenant could
577	 * have planted (see taskBackup). */
578	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
579	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
580	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
581	  if (!b) throw new Error("backup not found");
582	  const u = a.username;
583	  const { home, webroot } = accountPaths(u);
584	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
585	  const stage = `/var/hosting-backups/${u}/.restore`;
586	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
587	  // Files: the archive root holds ${u}/… — copy it back over the home.
588	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
589	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
590	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
591	  // another tenant's DB is never fed to mysql.
592	  await run(
593	    conn,
594	    "restore dbs",
595	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
596	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
597	  );
598	  // Re-assert the hardened perms the restored tree may have flattened: webroot
599	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
600	  const rfs = accountFsPlan(u);
601	  await run(
602	    conn,
603	    "fix perms",
604	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
605	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
606	  );
607	}
