609	async function processHostingTask(taskId: string): Promise<void> {
610	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
611	  if (!task || task.status !== "PENDING") return;
612	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
613	  const a = task.account;
614	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
615	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
616	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
617	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
618	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
619	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
620	  try {
621	    const conn = await connectNode(a.node);
622	    try {
623	      let result: string | null = null;
624	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
625	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
626	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
627	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
628	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
629	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
630	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
631	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
632	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
633	    } finally { try { conn.end(); } catch { /* */ } }
634	  } catch (e) {
635	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
636	  }
637	}
