639	export async function hostingTaskSweep(): Promise<void> {
640	  if (SANDBOX) {
641	    const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true, kind: true, account: { select: { primaryDomain: true } } }, take: 10 });
