/** Write a vhost file + enable it, tested before reload. */
async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
}

/**
 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
 * interpolation reaches a shell here (the caller validated every part).
 */
function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
  const phpLoc = [
    `    location ~ \\.php$ {`,
    `        include fastcgi_params;`,
    `        fastcgi_pass unix:${sock};`,
    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
    `    }`,
  ].join("\n");
  const body = [
    `    root ${docroot};`,
    `    index index.php index.html;`,
    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
    phpLoc,
    `    location ~ /\\. { deny all; }`,
  ].join("\n");
  const http = [
    `server {`,
    `    listen 80;`,
    `    listen [::]:80;`,
    `    server_name ${serverName};`,
    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
    `}`,
  ].join("\n");
  if (!sslLiveDir) return http + "\n";
  const https = [
    `server {`,
    `    listen 443 ssl;`,
    `    listen [::]:443 ssl;`,
    `    server_name ${serverName};`,
    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
    `    ssl_protocols TLSv1.2 TLSv1.3;`,
    body,
    `}`,
  ].join("\n");
  return `${http}\n${https}\n`;
}

/** Write + enable a vhost under an arbitrary key (hosting-<key>.conf), tested
 *  before reload. Used for subdomain / addon-domain sites (key = <user>-<label>
 *  or <user>-<domain>); the account's own primary vhost keeps its <user> filename. */
async function installNamedVhost(conn: Client, key: string, conf: string): Promise<void> {
  const path = `/etc/nginx/sites-available/hosting-${key}.conf`;
  await run(conn, "write site vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${key}.conf`);
  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
}

/** Remove a named site vhost (enabled + available), tested before reload. */
async function removeNamedVhost(conn: Client, key: string): Promise<void> {
  await run(conn, "remove site vhost", `rm -f /etc/nginx/sites-enabled/hosting-${key}.conf /etc/nginx/sites-available/hosting-${key}.conf; nginx -t && systemctl reload nginx || true`);
}

// ---- Subdomains + addon domains + cron (cPanel-class site mgmt) -------------
// Each runs on an ACTIVE account and touches only THIS account's own files: a
// docroot jailed under /home/<user>, a vhost keyed hosting-<user>-<name>.conf,
// or the account user's own crontab. Every value is re-validated here (never
// trusted from the DB) before it reaches a shell.

type SiteAccount = { id: string; username: string; primaryDomain: string };

/** Owner+group+mode for a new site docroot — same hardened plan as the primary
 *  webroot (owner rw, www-data group r-x for nginx, world nothing). */
async function makeSiteDocroot(conn: Client, u: string, dir: string, docroot: string, title: string): Promise<void> {
  const fs = accountFsPlan(u);
  await run(
    conn,
    "site docroot",
    `mkdir -p ${docroot} && chown ${fs.webroot.owner} ${dir} ${docroot} && chmod ${fs.webroot.mode} ${dir} ${docroot} && ` +
      `{ [ -f ${docroot}/index.html ] || { printf '<!doctype html><meta charset=utf-8><title>%s</title><h1>%s</h1><p>This site is ready. Upload your files here.</p>' '${title}' '${title}' > ${docroot}/index.html && chown ${fs.webroot.owner} ${docroot}/index.html; }; }`,
  );
}

async function taskCreateSubdomain(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const subdomainId = String(JSON.parse(payload || "{}").subdomainId ?? "");
  const sub = await db.hostingSubdomain.findFirst({ where: { id: subdomainId, accountId: a.id } });
  if (!sub) throw new Error("subdomain not found");
  try {
    const u = a.username;
    const label = sub.label;
    if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
    if (!isValidSubdomainLabel(label)) throw new Error("unsafe subdomain label");
    const fqdn = `${label}.${a.primaryDomain}`;
    if (!isValidHostingDomain(fqdn)) throw new Error("unsafe subdomain hostname");
    const { dir, docroot } = subdomainPaths(u, label);
    await makeSiteDocroot(conn, u, dir, docroot, fqdn);
    await installNamedVhost(conn, `${u}-${label}`, renderSiteVhost(fqdn, docroot, `/run/php/${u}.sock`, null));
    await db.hostingSubdomain.update({ where: { id: sub.id }, data: { status: "ACTIVE" } });
  } catch (e) {
    await db.hostingSubdomain.update({ where: { id: sub.id }, data: { status: "FAILED" } }).catch(() => undefined);
    throw e;
  }
}

async function taskDeleteSubdomain(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const subdomainId = String(JSON.parse(payload || "{}").subdomainId ?? "");
  const sub = await db.hostingSubdomain.findFirst({ where: { id: subdomainId, accountId: a.id } });
  const u = a.username;
  if (sub && isValidUnixUsername(u) && isValidSubdomainLabel(sub.label)) {
    const { dir } = subdomainPaths(u, sub.label);
    await removeNamedVhost(conn, `${u}-${sub.label}`);
    await run(conn, "remove subdomain docroot", `rm -rf ${dir}`);
  }
  await db.hostingSubdomain.delete({ where: { id: subdomainId } }).catch(() => undefined);
}

async function taskCreateAddonDomain(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const addonId = String(JSON.parse(payload || "{}").addonId ?? "");
  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
  if (!addon) throw new Error("addon domain not found");
  try {
    const u = a.username;
    const d = addon.domain;
    if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
    if (!isValidHostingDomain(d)) throw new Error("unsafe addon domain");
    const { dir, docroot } = addonDomainPaths(u, d);
    await makeSiteDocroot(conn, u, dir, docroot, d);
    await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, null));
    await db.hostingAddonDomain.update({ where: { id: addon.id }, data: { status: "ACTIVE" } });
  } catch (e) {
    await db.hostingAddonDomain.update({ where: { id: addon.id }, data: { status: "FAILED" } }).catch(() => undefined);
    throw e;
  }
}

async function taskDeleteAddonDomain(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const addonId = String(JSON.parse(payload || "{}").addonId ?? "");
  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
  const u = a.username;
  if (addon && isValidUnixUsername(u) && isValidHostingDomain(addon.domain)) {
    const { dir } = addonDomainPaths(u, addon.domain);
    await removeNamedVhost(conn, `${u}-${addon.domain}`);
    await run(conn, "remove addon docroot", `rm -rf ${dir}`);
  }
  await db.hostingAddonDomain.delete({ where: { id: addonId } }).catch(() => undefined);
}

/** (Re)write the account user's crontab from its ACTIVE cron rows. Runs `crontab
 *  -u <user>` so every command runs AS the jailed user (confined). The whole
 *  crontab is rebuilt each time (idempotent); a quoted heredoc prevents any shell
 *  expansion, and each line is re-validated so nothing unsafe is ever written. */
async function writeUserCrontab(conn: Client, username: string, accountId: string): Promise<void> {
  if (!isValidUnixUsername(username)) throw new Error("unsafe account username");
  const crons = await db.hostingCron.findMany({ where: { accountId, status: "ACTIVE" }, orderBy: { createdAt: "asc" } });
  const lines = crons
    .filter((c) => isValidCronSchedule(c.schedule) && isValidCronCommand(c.command))
    .map((c) => `${c.schedule} ${c.command}`);
  if (lines.length === 0) {
    await run(conn, "clear crontab", `crontab -u ${username} -r 2>/dev/null || true`);
    return;
  }
  const body = lines.join("\n") + "\n";
  await run(conn, "write crontab", `crontab -u ${username} - <<'NXCRONEOF'\n${body}NXCRONEOF`);
}

async function taskCreateCron(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const cronId = String(JSON.parse(payload || "{}").cronId ?? "");
  const cron = await db.hostingCron.findFirst({ where: { id: cronId, accountId: a.id } });
  if (!cron) throw new Error("cron not found");
  try {
    if (!isValidCronSchedule(cron.schedule) || !isValidCronCommand(cron.command)) throw new Error("unsafe cron entry");
    await db.hostingCron.update({ where: { id: cron.id }, data: { status: "ACTIVE" } });
    await writeUserCrontab(conn, a.username, a.id);
  } catch (e) {
    await db.hostingCron.update({ where: { id: cron.id }, data: { status: "FAILED" } }).catch(() => undefined);
    throw e;
  }
}

async function taskDeleteCron(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
  const cronId = String(JSON.parse(payload || "{}").cronId ?? "");
  await db.hostingCron.delete({ where: { id: cronId } }).catch(() => undefined);
  await writeUserCrontab(conn, a.username, a.id);
}

