"use client";

import { useEffect, useRef, useState } from "react";
import { hostingListFiles, hostingMkdir, hostingDeleteFile, type FsEntryView } from "@/lib/actions-hosting";

/** In-browser file manager for a hosting account. Extracted verbatim from the old
 *  HostingClient; behaviour is identical. */
export function FileManager({ accountId }: { accountId: string }) {
  const [open, setOpen] = useState(false);
  const [path, setPath] = useState("public_html");
  const [entries, setEntries] = useState<FsEntryView[]>([]);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  async function load(p: string) {
    setBusy(true); setErr("");
    const r = await hostingListFiles(accountId, p);
    setBusy(false); setLoaded(true);
    if (r.error) setErr(r.error); else { setEntries(r.entries ?? []); setPath(r.path ?? p); }
  }
  useEffect(() => { if (open) load(path); /* eslint-disable-next-line */ }, [open]);

  const parent = () => { const parts = path.split("/").filter(Boolean); parts.pop(); load(parts.join("/") || "public_html"); };
  async function upload(files: FileList | null) {
    if (!files?.length) return;
    setBusy(true);
    for (const f of Array.from(files)) {
      const fd = new FormData(); fd.append("file", f);
      await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd }).catch(() => {});
    }
    if (fileRef.current) fileRef.current.value = "";
    load(path);
  }

  if (!open) return <button className="text-xs font-medium text-brand-300 hover:underline" onClick={() => setOpen(true)}>Open file manager</button>;
  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
      <div className="mb-2 flex items-center justify-between">
        <span className="font-mono text-xs text-slate-400">/{path}</span>
        <div className="flex items-center gap-2 text-xs">
          <button className="text-brand-300 hover:underline" onClick={() => fileRef.current?.click()}>Upload</button>
          <input ref={fileRef} type="file" multiple className="hidden" onChange={(e) => upload(e.target.files)} />
          <button className="text-slate-400 hover:underline" onClick={async () => { const n = prompt("New folder name"); if (n) { const r = await hostingMkdir(accountId, path, n); if (r.error) alert(r.error); else load(path); } }}>New folder</button>
          <button className="text-slate-500 hover:underline" onClick={() => setOpen(false)}>close</button>
        </div>
      </div>
      {err && <p className="text-xs text-amber-300">{err}</p>}
      {busy && <p className="text-xs text-slate-500">Loading…</p>}
      {loaded && !busy && !err && entries.length === 0 && path === "public_html" && (
        <p className="px-1 py-2 text-xs text-slate-500">This folder is empty. Upload your site files here, or install an app.</p>
      )}
      <ul className="max-h-56 overflow-auto text-xs">
        {path !== "public_html" && path !== "" && (
          <li><button className="text-slate-400 hover:underline" onClick={parent}>⬆ ..</button></li>
        )}
        {entries.map((e) => (
          <li key={e.name} className="flex items-center justify-between py-0.5">
            {e.isDir ? (
              <button className="text-brand-200 hover:underline" onClick={() => load(`${path}/${e.name}`)}>📁 {e.name}</button>
            ) : (
              <a className="text-slate-300 hover:underline" href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${e.name}`)}`}>📄 {e.name}</a>
            )}
            <span className="flex items-center gap-2 text-slate-500">
              {!e.isDir && <span>{(e.size / 1024).toFixed(0)} KB</span>}
              <button className="text-red-400 hover:underline" onClick={async () => { if (confirm(`Delete ${e.name}?`)) { const r = await hostingDeleteFile(accountId, `${path}/${e.name}`, e.isDir); if (r.error) alert(r.error); else load(path); } }}>del</button>
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

