import { useEffect, useState } from "react";
import { installApp, installWordPress, listAppCatalog } from "@/lib/actions-hosting";

/** One-click app installer dropdown (WordPress + catalog). Extracted verbatim
 *  from the old HostingClient; behaviour is identical. */
export function AppInstaller({ accountId }: { accountId: string }) {
  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
  const [busy, setBusy] = useState(false);
  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);
