import { useEffect, useState } from "react";
import { createHostingDatabase, listHostingDatabases, type HostingDbView } from "@/lib/actions-hosting";

/** Database create/list UI for a hosting account. Extracted from the old
 *  HostingClient AccountCard; behaviour is identical, plus a disabled
 *  phpMyAdmin placeholder (wiring is a TODO for the platform owner). */
export function DatabasesPanel({ accountId, username, maxDatabases }: { accountId: string; username: string; maxDatabases: number }) {
  const [dbs, setDbs] = useState<HostingDbView[]>([]);
  const [dbLabel, setDbLabel] = useState("");
  const [dbBusy, setDbBusy] = useState(false);
  const [dbErr, setDbErr] = useState("");
  const [newDbPassword, setNewDbPassword] = useState<{ name: string; password: string } | null>(null);

  useEffect(() => { listHostingDatabases(accountId).then(setDbs).catch(() => {}); }, [accountId]);

  async function addDb() {
    if (!dbLabel.trim()) return;
    setDbBusy(true);
    setDbErr("");
    try {
      const res = await createHostingDatabase(accountId, dbLabel.trim());
      if (res.error) setDbErr(res.error);
      else {
        setNewDbPassword({ name: `${username}_${dbLabel.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db"}`, password: res.password ?? "" });
        setDbLabel("");
        listHostingDatabases(accountId).then(setDbs).catch(() => {});
      }
    } finally {
      setDbBusy(false);
    }
  }

  if (maxDatabases <= 0) {
    return <p className="text-sm text-slate-400">Databases aren’t included on this plan. Upgrade to add MySQL databases.</p>;
  }

  return (
    <div className="space-y-4">
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
        <div className="mb-1 flex items-center justify-between">
          <p className="text-sm font-medium text-slate-300">
            Databases <span className="text-xs text-slate-500">({dbs.length}/{maxDatabases})</span>
          </p>
          <button
            type="button"
            disabled
            title="phpMyAdmin is coming soon"
            className="cursor-not-allowed rounded-lg border border-white/10 bg-white/[0.03] px-2.5 py-1 text-xs text-slate-500"
          >
            Open phpMyAdmin — coming soon
          </button>
        </div>
        {dbs.length > 0 && (
          <ul className="mb-2 space-y-0.5 text-xs">
            {dbs.map((d) => (
              <li key={d.id} className="flex items-center gap-2 text-slate-400">
                <span className="font-mono text-slate-200">{d.name}</span>
                <span className="text-slate-500">user {d.dbUser}</span>
                <span className={d.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{d.status.toLowerCase()}</span>
              </li>
            ))}
          </ul>
        )}
        {newDbPassword && (
          <div className="mb-2 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-200">
            Created <span className="font-mono">{newDbPassword.name}</span> — password (shown once):{" "}
            <span className="font-mono">{newDbPassword.password}</span>
          </div>
        )}
        {dbs.length < maxDatabases ? (
          <div className="flex items-center gap-2">
            <input className="input flex-1 text-xs" placeholder="database name" value={dbLabel} onChange={(e) => setDbLabel(e.target.value)} />
            <button className="btn-secondary text-xs" disabled={dbBusy || !dbLabel.trim()} onClick={addDb}>{dbBusy ? "…" : "Create"}</button>
          </div>
        ) : (
          <p className="text-xs text-slate-500">You’ve used all the databases on your plan.</p>
        )}
        {dbErr && <p className="mt-1 text-xs text-amber-300">{dbErr}</p>}
      </div>
    </div>
  );
}

