import { useCallback, useEffect, useState } from "react";
import {
  listHostingSubdomains,
  createSubdomain,
  deleteSubdomain,
  type HostingSubdomainView,
} from "@/lib/actions-hosting";
import { StatusPill } from "@/components/customer/cpanel/shared";

export function SubdomainsPanel({
  accountId,
  primaryDomain,
  pointToA,
  onCount,
}: {
  accountId: string;
  primaryDomain: string;
  pointToA: string;
  onCount?: (n: number) => void;
}) {
  const [rows, setRows] = useState<HostingSubdomainView[] | null>(null);
  const [label, setLabel] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const refresh = useCallback(() => {
    listHostingSubdomains(accountId).then((r) => { setRows(r); onCount?.(r.filter((s) => s.status !== "DELETING").length); }).catch(() => setRows([]));
  }, [accountId, onCount]);

  useEffect(() => { refresh(); }, [refresh]);
  // Poll while anything is settling.
  useEffect(() => {
    if (!rows?.some((r) => r.status === "PENDING" || r.status === "DELETING")) return;
    const t = setInterval(refresh, 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  async function add() {
    if (!label.trim()) return;
    setBusy(true); setErr("");
    const r = await createSubdomain(accountId, label.trim());
    setBusy(false);
    if (r.error) setErr(r.error);
    else { setLabel(""); refresh(); }
  }

  return (
    <div className="card">
      <h3 className="mb-1 font-semibold">Subdomains</h3>
      <p className="mb-4 text-sm text-slate-400">
        Create a subdomain of <span className="font-mono text-slate-300">{primaryDomain}</span> with its own folder and site.
      </p>

