            <span className="whitespace-nowrap font-mono text-xs text-slate-500">.{primaryDomain}</span>
          </div>
        </div>
        <button className="btn-primary" disabled={busy || !label.trim()} onClick={add}>{busy ? "Creating…" : "Add subdomain"}</button>
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      <p className="mt-2 text-xs text-slate-500">
