        ) : (
          <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-lg border border-white/[0.06]">
            {rows.map((s) => {
              const settling = s.status === "PENDING" || s.status === "DELETING";
              return (
                <li key={s.id} className="flex flex-wrap items-center justify-between gap-2 bg-white/[0.02] px-3 py-2">
                  <div className="flex items-center gap-2">
                    <a href={`http://${s.fqdn}`} target="_blank" rel="noreferrer" className="font-mono text-sm text-slate-200 hover:underline">{s.fqdn}</a>
                    <StatusPill status={s.status} />
                  </div>
                  <button
                    className="btn-danger px-2.5 py-1 text-xs"
                    disabled={settling}
                    onClick={() => { if (confirm(`Delete ${s.fqdn}? Its files will be removed.`)) deleteSubdomain(s.id).then((r) => { if (r.error) alert(r.error); else refresh(); }); }}
                  >
                    Delete
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

