"use client";

import { useState } from "react";
import Link from "next/link";
import { orderHostingAccount, retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";
import { recommendHostingPlan } from "@/lib/hosting/recommend";

type PlanView = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  mailboxes: number;
  freeMigration: boolean;
  featured: boolean;
  tagline: string;
};

export function HostingClient({ plans, accounts }: { plans: PlanView[]; accounts: HostingAccountView[] }) {
  const [domain, setDomain] = useState("");
  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [ok, setOk] = useState("");

  async function order() {
    if (!planId || !domain.trim()) return;
    setBusy(true);
    setError("");
    setOk("");
    try {
      const res = await orderHostingAccount(planId, domain.trim());
      if (res.error) setError(res.error);
      else {
        setOk("Account created — it’s being set up now.");
        setDomain("");
        setTimeout(() => window.location.reload(), 900);
      }
    } catch {
      setError("Something went wrong. Your wallet was not charged — try again.");
    } finally {
      setBusy(false);
    }
  }

  async function retry(id: string) {
    await retryHostingProvision(id);
    window.location.reload();
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-xl font-semibold">Web Hosting</h1>
        <p className="mt-1 text-sm text-slate-400">
          Host your website without managing a server — we run PHP, databases, email and SSL for you. Point your
          domain at us and you’re live.
        </p>
      </div>

      {/* Your accounts — compact cards linking to the per-account dashboard. */}
      {accounts.length > 0 ? (
        <div className="space-y-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {accounts.map((a) => (
              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
            ))}
          </div>
        </div>
      ) : (
        <EmptyState
          title="No hosting accounts yet"
          sub="Pick a plan below, enter your domain, and we’ll set up an isolated hosting account for you in a minute."
        />
      )}

      {/* Order a (new) site. */}
      <div className="card">
        <h2 className="mb-1 font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
        <p className="mb-3 text-xs text-slate-500">Each site gets its own isolated account, storage quota and databases.</p>
        {error && <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
        {ok && <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{ok}</div>}
        {plans.length === 0 ? (
          <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
        ) : (
          <>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {plans.map((p) => {
                const rec = recommendHostingPlan(p);
                const selected = planId === p.id;
                return (
                  <button
                    key={p.id}
                    type="button"
                    onClick={() => setPlanId(p.id)}
                    className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
                      selected ? "border-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
                    }`}
                  >
                    {p.featured && (
                      <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
                        Most popular
                      </span>
                    )}
                    <div className="flex items-baseline justify-between">
                      <span className="font-medium">{p.name}</span>
                      <span className="text-sm font-semibold">
                        {fmtMoney(p.priceCents)}
                        <span className="text-xs text-slate-500">/mo</span>
                      </span>
                    </div>
                    <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
                    <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
                      <li>{p.diskGB} GB NVMe SSD storage</li>
                      <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
                      <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
                      <li>{p.bandwidthTB} TB bandwidth</li>
                      <li>{p.mailboxes} email mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
                      {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
                    </ul>
                    <p className="mt-2 text-[11px] leading-snug text-slate-500">{rec.detail}</p>
                  </button>
                );
              })}
            </div>
            <div className="mt-4 flex flex-wrap items-end gap-3">
              <div className="min-w-[220px] flex-1">
                <label className="label">Your domain</label>
                <input className="input" placeholder="example.com" value={domain} onChange={(e) => setDomain(e.target.value)} />
              </div>
              <button className="btn-primary" disabled={busy || !planId || !domain.trim()} onClick={order}>
                {busy ? "Creating…" : "Create account"}
              </button>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Charged from your wallet. You don’t need to move your domain yet — you’ll get the exact DNS record to set
              after it’s created.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- card --- */

function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
  const diskGB = Math.round(a.diskQuotaMB / 1024);
  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;

  const body = (
    <>
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
        </div>
        <StatusDot status={a.status} />
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
      </div>
    </>
  );

  // A failed account can't be opened usefully — show the retry affordance inline.
  if (a.status === "FAILED") {
    return (
      <div className="card">
        {body}
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
        </div>
      </div>
    );
  }

  return (
    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
      {body}
      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
    </Link>
  );
}

import { notFound } from "next/navigation";
import { getHostingAccount } from "@/lib/actions-hosting";
import { StatusDot, Badge } from "@/components/ui/primitives";
import { HostingTabs } from "@/components/customer/hosting/HostingTabs";

export const dynamic = "force-dynamic";

export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string }>;
}) {
  const [{ id }, { tab }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  return (
    <div>
      <div className="mb-6">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="page-title">{account.primaryDomain}</h1>
          <StatusDot status={account.status} />
          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        </div>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <Badge tone="slate">{account.planName}</Badge>
          <Badge tone="slate">PHP {account.phpVersion}</Badge>
          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
        </div>
      </div>

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          Your account is being set up — this usually takes under a minute. Refresh to see it come online.
        </div>
      )}

      <HostingTabs account={account} initialTab={tab} />
    </div>
  );
}

